class BizException extends Error {
  constructor(code, message){ super(message); this.code = code; this.biz = true; }
}

function validate(dto, rules) {
  const errors = [];
  for (const [field, rule] of Object.entries(rules)) {
    const v = dto[field];
    if (rule.notNull && (v === null || v === undefined)) errors.push(field + " 不能为空");
    if (rule.size && typeof v === "string" && (v.length < rule.size.min || v.length > rule.size.max))
      errors.push(field + " 长度需在 " + rule.size.min + "-" + rule.size.max + " 之间");
  }
  return errors;
}
const rules = { name: { notNull: true, size: { min: 2, max: 10 } }, age: { notNull: true } };
console.log(JSON.stringify(validate({ name: "A", age: 20 }, rules)));
console.log(JSON.stringify(validate({ age: null }, rules)));
